/**
 * Context-aware guidance — transparent, rule-based.
 *
 * Every card comes from a named rule with a readable trigger. Nothing here is
 * generated by a language model or learned from data. Thresholds are
 * illustrative defaults for a prototype and should be reviewed against
 * literature and local guidance before real-world use.
 */
import type {
  GuidanceThresholds,
  HourlyOutlook,
  Prediction,
  Recommendation,
  RecommendationSeverity,
  Room,
  SensorReading,
  SupportingDatum,
  WeatherData,
} from '@/types'
import { fmtDelta, fmtPct, fmtPm, fmtTemp, pm25Category } from '@/lib/format'
import { round } from '@/lib/utils'
import { compassLabel, hasOppositeOpenings, ventilationWalls, wallFacing } from '@/features/rooms/roomGeometry'

export const GUIDANCE_THRESHOLDS: GuidanceThresholds = {
  /** indoor (or forecast) temperature at which the overheating rule fires */
  warmIndoorC: 29,
  hotIndoorC: 31,
  /** NWS heat index bands, °C (caution 27–32, extreme caution 32–39, danger ≥ 39) */
  heatIndexExtremeCautionC: 32,
  heatIndexDangerC: 39,
  /** outdoor must be at least this much cooler than indoors to suggest ventilation */
  ventilationCoolerByC: 1,
  /** US EPA 24-h PM2.5 breakpoint for "unhealthy for sensitive groups" */
  pm25CautionUgm3: 35.4,
  pm25UnhealthyUgm3: 55.4,
  rainProbabilityPct: 60,
  highHumidityPct: 70,
  fanUsefulFromC: 28,
}

export interface GuidanceInput {
  room: Room
  reading: SensorReading | null
  weather: WeatherData | null
  prediction: Prediction | null
  outlook: HourlyOutlook[] | null
  /** local hour, 0–23 */
  hour: number
  /** user-adjustable thresholds; defaults to GUIDANCE_THRESHOLDS */
  thresholds?: GuidanceThresholds
}

export interface RuleEvaluation {
  ruleId: string
  name: string
  triggered: boolean
  reason: string
}

export interface GuidanceResult {
  recommendations: Recommendation[]
  evaluations: RuleEvaluation[]
  dataValid: { indoor: boolean; outdoor: boolean; prediction: boolean }
}

const SEVERITY_ORDER: Record<RecommendationSeverity, number> = { caution: 0, consider: 1, info: 2 }

/** NWS Rothfusz regression; returns °C. Only meaningful for T ≥ 26.7 °C and RH ≥ 40 %. */
export function heatIndexC(tempC: number, rh: number): number | null {
  if (tempC < 26.7 || rh < 40) return null
  const T = (tempC * 9) / 5 + 32
  const R = rh
  const hi =
    -42.379 +
    2.04901523 * T +
    10.14333127 * R -
    0.22475541 * T * R -
    0.00683783 * T * T -
    0.05481717 * R * R +
    0.00122874 * T * T * R +
    0.00085282 * T * R * R -
    0.00000199 * T * T * R * R
  return round(((hi - 32) * 5) / 9, 1)
}

const SUN_WEST = new Set(['W', 'SW', 'NW'])
const SUN_EAST = new Set(['E', 'SE', 'NE'])

export function evaluateGuidance(input: GuidanceInput): GuidanceResult {
  const { room, reading, weather, prediction, outlook, hour } = input
  const T = input.thresholds ?? GUIDANCE_THRESHOLDS
  const recs: Recommendation[] = []
  const evals: RuleEvaluation[] = []

  const indoorT = reading?.status === 'ok' ? reading.temperatureC : null
  const indoorRH = reading?.status === 'ok' ? reading.humidityPct : null
  const outdoorT = weather?.temperatureC ?? null
  const pm = weather?.pm25 ?? null
  const predOk = prediction?.status === 'ok' && prediction.predictedTempC != null
  const predicted = predOk ? prediction!.predictedTempC : null
  const operableWindows = room.windows.filter((w) => w.operable)
  const srcIndoor = reading ? (reading.source === 'demo' ? 'Demo sensor' : 'Room sensor') : undefined
  const srcWeather = weather?.sourceLabel
  const srcPred = prediction ? (prediction.isDemo ? 'Demo forecast (not a model)' : prediction.modelName) : undefined

  const dataValid = { indoor: indoorT != null, outdoor: outdoorT != null, prediction: predOk }

  // -------------------------------------------------------------- data quality
  {
    const problems: string[] = []
    if (!dataValid.indoor) problems.push('no recent indoor reading')
    if (!dataValid.outdoor) problems.push('no outdoor weather data')
    if (!dataValid.prediction) problems.push('no valid forecast')
    const triggered = problems.length > 0
    evals.push({
      ruleId: 'data-validity',
      name: 'Check measurement and prediction validity',
      triggered,
      reason: triggered ? `Missing: ${problems.join(', ')}.` : 'Indoor reading, weather and forecast are all available.',
    })
    if (triggered) {
      recs.push({
        id: 'rec-data',
        ruleId: 'data-validity',
        title: 'Some data is unavailable',
        category: 'data-quality',
        severity: dataValid.indoor ? 'info' : 'caution',
        detectedCondition: `The guidance below was produced with ${problems.join(', ')}.`,
        suggestion: dataValid.indoor
          ? 'Treat forecast-based guidance as unavailable until the prediction service responds.'
          : 'Check that the room sensor is powered and connected. Rules that need indoor values are skipped meanwhile.',
        rationale: 'Guidance is only as reliable as its inputs. Rules are skipped rather than guessed when inputs are missing.',
        supportingData: [
          { label: 'Indoor reading', value: reading ? reading.status : 'none', source: srcIndoor },
          { label: 'Weather data', value: weather ? 'available' : 'missing', source: srcWeather },
          { label: 'Forecast', value: prediction?.status ?? 'none', source: srcPred },
        ],
        limitations: 'Fewer cards does not mean conditions are fine — it may mean the app could not check them.',
        ruleDescription: 'Fires when the indoor reading, outdoor weather or forecast is missing or invalid.',
      })
    }
  }

  // -------------------------------------------------------------- overheating
  {
    const hi = indoorT != null && indoorRH != null ? heatIndexC(indoorT, indoorRH) : null
    const hot = (indoorT ?? -Infinity) >= T.warmIndoorC || (predicted ?? -Infinity) >= T.warmIndoorC
    const triggered = hot || (hi ?? 0) >= T.heatIndexExtremeCautionC
    evals.push({
      ruleId: 'overheating',
      name: 'Potential indoor overheating',
      triggered,
      reason:
        indoorT == null
          ? 'Skipped: no indoor temperature.'
          : `Indoor ${fmtTemp(indoorT)}, forecast ${fmtTemp(predicted)}, heat index ${fmtTemp(hi)}; fires at ≥ ${T.warmIndoorC}°C or heat index ≥ ${T.heatIndexExtremeCautionC}°C.`,
    })
    if (triggered && indoorT != null) {
      const severe = indoorT >= T.hotIndoorC || (hi ?? 0) >= T.heatIndexDangerC
      const rising = predicted != null && predicted - indoorT >= 0.3
      const data: SupportingDatum[] = [
        { label: 'Indoor temperature', value: fmtTemp(indoorT), source: srcIndoor },
        { label: 'Indoor humidity', value: fmtPct(indoorRH), source: srcIndoor },
      ]
      if (hi != null) data.push({ label: 'Heat index (NWS formula)', value: fmtTemp(hi) })
      if (predicted != null) data.push({ label: 'Forecast in 60 min', value: `${fmtTemp(predicted)} (${fmtDelta(prediction!.deltaC)})`, source: srcPred })
      recs.push({
        id: 'rec-heat',
        ruleId: 'overheating',
        title: 'Potential indoor overheating',
        category: 'heat',
        severity: severe ? 'caution' : 'consider',
        detectedCondition: `The room is at ${fmtTemp(indoorT)}${rising ? ' and the forecast suggests it may keep warming' : ''}.`,
        suggestion:
          'Consider reducing heat gains: draw curtains or blinds on sun-facing windows, switch off unused heat-producing appliances, use a fan if available, drink water, and check on older or unwell household members.',
        rationale:
          'Warm, humid rooms make it harder for the body to shed heat, which can affect sleep and wellbeing, especially for vulnerable people.',
        supportingData: data,
        limitations: `The ${T.warmIndoorC}°C threshold is an illustrative default, not a medical limit. Comfort depends on clothing, activity, acclimatisation and air movement. Sensor placement affects readings.`,
        ruleDescription: `Indoor or forecast temperature ≥ ${T.warmIndoorC}°C, or heat index ≥ ${T.heatIndexExtremeCautionC}°C.`,
      })
    }
  }

  // -------------------------------------------------------------- ventilation
  {
    const rainNow = weather?.rainProbabilityPct ?? 0
    let triggered = false
    let reason = ''
    if (!operableWindows.length) reason = 'Skipped: this room has no openable windows recorded.'
    else if (indoorT == null || outdoorT == null) reason = 'Skipped: needs both indoor and outdoor temperature.'
    else {
      triggered = true
      reason = `Outdoor ${fmtTemp(outdoorT)} vs indoor ${fmtTemp(indoorT)}.`
    }
    evals.push({ ruleId: 'ventilation', name: 'Natural ventilation considerations', triggered, reason })

    if (triggered && indoorT != null && outdoorT != null) {
      const diff = round(outdoorT - indoorT, 1)
      const cooler = diff <= -T.ventilationCoolerByC
      const warmer = diff >= 0.5
      const airOk = pm == null || pm <= T.pm25CautionUgm3
      const rainOk = rainNow < T.rainProbabilityPct
      const cross = hasOppositeOpenings(room)
      const walls = ventilationWalls(room)

      let detected: string
      let suggestion: string
      let severity: RecommendationSeverity = 'info'
      if (cooler && airOk && rainOk) {
        severity = 'consider'
        detected = `Outdoor air is about ${Math.abs(diff).toFixed(1)}°C cooler than the room, with no strong air-quality or rain signals.`
        suggestion = cross
          ? 'Conditions may suit opening windows on opposite sides of the room for a while. Leave internal doors open if that helps air pass through.'
          : 'Conditions may suit opening windows for a while. With openings on one side only, exchange tends to be slower; an internal door or fan can help.'
      } else if (warmer) {
        detected = `Outdoor air is about ${diff.toFixed(1)}°C warmer than the room.`
        suggestion =
          'Opening windows now may let warmer air in. Consider keeping them mostly closed and shaded during the warmest hours, and ventilating later when it is cooler outside.'
      } else {
        detected = `Indoor and outdoor temperatures are similar (difference ${fmtDelta(diff)}).`
        suggestion =
          'Ventilation now is mainly useful for fresh air rather than cooling. Short airing periods may be enough.'
        if (!airOk) suggestion += ' Outdoor PM2.5 is elevated, so keep airing brief.'
        if (!rainOk) suggestion += ' Rain is likely soon.'
      }
      recs.push({
        id: 'rec-vent',
        ruleId: 'ventilation',
        title: 'Natural ventilation considerations',
        category: 'ventilation',
        severity,
        detectedCondition: detected,
        suggestion,
        rationale:
          'Bringing in outdoor air helps cooling only when that air is cooler than indoor air. Pollution and rain can make opening windows less desirable.',
        supportingData: [
          { label: 'Indoor temperature', value: fmtTemp(indoorT), source: srcIndoor },
          { label: 'Outdoor temperature', value: fmtTemp(outdoorT), source: srcWeather },
          { label: 'Outdoor PM2.5 (regional)', value: fmtPm(pm), source: weather?.pm25Source },
          { label: 'Openable windows', value: `${operableWindows.length} on ${walls.length} wall(s)${cross ? ', opposite sides' : ''}` },
        ],
        limitations:
          'This is a comparison of two temperatures, not an airflow simulation. Actual air exchange depends on wind, neighbouring buildings, opening sizes and door positions, and the app cannot estimate how much the room will cool.',
        ruleDescription: `Compares outdoor and indoor temperature; suggests airing when outdoor is ≥ ${T.ventilationCoolerByC}°C cooler, PM2.5 ≤ ${T.pm25CautionUgm3} µg/m³ and rain probability < ${T.rainProbabilityPct}%.`,
      })
    }
  }

  // -------------------------------------------------------------- air quality
  {
    const triggered = pm != null && pm > T.pm25CautionUgm3
    evals.push({
      ruleId: 'air-quality',
      name: 'Outdoor air quality caution',
      triggered,
      reason: pm == null ? 'Skipped: no PM2.5 estimate.' : `Regional PM2.5 ${fmtPm(pm)}; fires above ${T.pm25CautionUgm3} µg/m³.`,
    })
    if (triggered && pm != null) {
      const cat = pm25Category(pm)
      recs.push({
        id: 'rec-air',
        ruleId: 'air-quality',
        title: 'Outdoor air quality caution',
        category: 'air-quality',
        severity: pm > T.pm25UnhealthyUgm3 ? 'caution' : 'consider',
        detectedCondition: `The regional outdoor PM2.5 estimate is ${fmtPm(pm)} (${cat.label.toLowerCase()} on the US EPA 24-hour scale).`,
        suggestion:
          'Consider limiting how long windows facing busy roads stay open, especially for children, older adults and people with heart or lung conditions. Shorter airing periods may be a reasonable compromise.',
        rationale: 'Fine particles can enter homes through open windows and are associated with respiratory and cardiovascular effects.',
        supportingData: [
          { label: 'Outdoor PM2.5 (regional)', value: fmtPm(pm), source: weather?.pm25Source },
          { label: 'Reference category', value: cat.label },
        ],
        limitations:
          'This is an outdoor regional estimate, not a measurement of your indoor air. Indoor PM2.5 can be higher or lower depending on cooking, smoking, filtration and building leakage.',
        ruleDescription: `Regional PM2.5 > ${T.pm25CautionUgm3} µg/m³.`,
      })
    }
  }

  // -------------------------------------------------------------- rain
  {
    const upcoming = (outlook ?? []).slice(0, 3)
    const maxProb = Math.max(weather?.rainProbabilityPct ?? 0, ...upcoming.map((o) => o.rainProbabilityPct))
    const triggered = operableWindows.length > 0 && maxProb >= T.rainProbabilityPct
    evals.push({
      ruleId: 'rain',
      name: 'Rain-related window reminder',
      triggered,
      reason: !operableWindows.length
        ? 'Skipped: no openable windows recorded.'
        : `Highest rain probability in the next 3 h: ${fmtPct(maxProb)}; fires at ≥ ${T.rainProbabilityPct}%.`,
    })
    if (triggered) {
      const unscreened = operableWindows.filter((w) => !w.hasScreen).length
      recs.push({
        id: 'rec-rain',
        ruleId: 'rain',
        title: 'Rain-related window reminder',
        category: 'rain',
        severity: 'consider',
        detectedCondition: `Rain is forecast as likely within the next few hours (up to ${fmtPct(maxProb)}).`,
        suggestion: `If windows are open, consider closing or partly closing them before rain arrives${unscreened ? `; ${unscreened} openable window(s) have no rain screen recorded` : ''}. After rain, cooler outdoor air may be worth letting in.`,
        rationale: 'Wind-driven rain can wet floors and furniture, and humidity rises during showers.',
        supportingData: [
          { label: 'Rain probability (now, 3 h window)', value: fmtPct(weather?.rainProbabilityPct), source: srcWeather },
          ...upcoming.map((o) => ({
            label: `Outlook ${new Date(o.timestamp).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`,
            value: fmtPct(o.rainProbabilityPct),
          })),
        ],
        limitations: 'Short-range rain forecasts for a single neighbourhood are uncertain; showers may arrive earlier, later or not at all.',
        ruleDescription: `Any rain probability ≥ ${T.rainProbabilityPct}% now or in the next 3 hourly outlook steps.`,
      })
    }
  }

  // -------------------------------------------------------------- shading & fan
  {
    const afternoon = hour >= 12 && hour < 18
    const morning = hour >= 6 && hour < 11
    const sunFacing = room.windows.filter((w) => {
      const f = wallFacing(w.wall, room.orientation)
      return !w.hasShading && ((afternoon && SUN_WEST.has(f)) || (morning && SUN_EAST.has(f)))
    })
    const fanUseful = room.hasCeilingFan && indoorT != null && indoorT >= T.fanUsefulFromC
    const triggered = sunFacing.length > 0 || fanUseful
    evals.push({
      ruleId: 'shading-fan',
      name: 'Shading or fan considerations',
      triggered,
      reason: `${sunFacing.length} unshaded window(s) facing the ${afternoon ? 'afternoon' : morning ? 'morning' : 'current'} sun; fan ${room.hasCeilingFan ? 'recorded' : 'not recorded'}${indoorT != null ? `, indoor ${fmtTemp(indoorT)}` : ''}.`,
    })
    if (triggered) {
      const parts: string[] = []
      if (sunFacing.length) {
        const names = sunFacing
          .map((w) => `${w.label} (${compassLabel[wallFacing(w.wall, room.orientation)].toLowerCase()}-facing)`)
          .join(', ')
        parts.push(`Consider closing curtains or blinds on ${names} while direct sun is likely.`)
      }
      if (fanUseful) parts.push('A ceiling fan may improve how comfortable the room feels by moving air across the skin.')
      recs.push({
        id: 'rec-shade',
        ruleId: 'shading-fan',
        title: 'Shading or fan considerations',
        category: 'shading',
        severity: 'consider',
        detectedCondition: sunFacing.length
          ? `${sunFacing.length} window(s) without recorded shading face the ${afternoon ? 'afternoon (west)' : 'morning (east)'} sun.`
          : `The room is at ${fmtTemp(indoorT)} and has a ceiling fan.`,
        suggestion: parts.join(' '),
        rationale:
          'Sunlight through glass adds heat that is then trapped indoors; shading outside the glass is generally more effective than inside. Moving air helps evaporative cooling of the body.',
        supportingData: [
          { label: 'Front wall faces', value: compassLabel[room.orientation] },
          { label: 'Unshaded sun-facing windows', value: String(sunFacing.length) },
          { label: 'Ceiling fan', value: room.hasCeilingFan ? 'Yes' : 'No' },
          { label: 'Local hour', value: `${String(hour).padStart(2, '0')}:00` },
        ],
        limitations:
          'Sun direction is approximated from the room orientation and time of day only; nearby buildings, trees and cloud cover are not considered. Fans do not lower air temperature and are less helpful in very hot conditions.',
        ruleDescription: 'Unshaded W/SW/NW windows from 12:00–18:00 or E/SE/NE windows from 06:00–11:00; or a fan with indoor ≥ 28°C.',
      })
    }
  }

  // -------------------------------------------------------------- humidity
  {
    const triggered = indoorRH != null && indoorRH >= T.highHumidityPct
    evals.push({
      ruleId: 'humidity',
      name: 'High indoor humidity',
      triggered,
      reason: indoorRH == null ? 'Skipped: no indoor humidity.' : `Indoor humidity ${fmtPct(indoorRH)}; fires at ≥ ${T.highHumidityPct}%.`,
    })
    if (triggered && indoorRH != null) {
      recs.push({
        id: 'rec-humid',
        ruleId: 'humidity',
        title: 'High indoor humidity',
        category: 'humidity',
        severity: 'info',
        detectedCondition: `Indoor relative humidity is ${fmtPct(indoorRH)}.`,
        suggestion:
          'If outdoor air is drier, short ventilation periods may help. Drying laundry indoors and long hot showers with closed doors add moisture.',
        rationale: 'Persistently humid rooms feel warmer and can encourage mould growth on cool surfaces.',
        supportingData: [
          { label: 'Indoor humidity', value: fmtPct(indoorRH), source: srcIndoor },
          { label: 'Outdoor humidity', value: fmtPct(weather?.humidityPct), source: srcWeather },
        ],
        limitations: 'Relative humidity changes with temperature; a single reading is a snapshot.',
        ruleDescription: `Indoor relative humidity ≥ ${T.highHumidityPct}%.`,
      })
    }
  }

  recs.sort((a, b) => SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity])
  return { recommendations: recs, evaluations: evals, dataValid }
}
